// .claude/settings.json: Run the script before the agent uses Edit or Write
{
  "hooks": {
    "PreToolUse": [{
      "matcher": "Edit|Write",
      "hooks": [{ "type": "command",
        "command": "\"$CLAUDE_PROJECT_DIR\"/.claude/hooks/protect-files.sh" }]
    }]
  }
}

-- Agent role: read only the tables it needs
GRANT SELECT ON products TO agent_ro;
-- Do not grant INSERT / UPDATE / DELETE or use an admin account

// Dangerous: concatenate model output directly into SQL
db.query(`SELECT * FROM orders WHERE ${llmFilter}`);
// Safer: have the model return only a value, validate it against an allowlist, and use a parameter
if (!ALLOWED_STATUS.includes(llmStatus)) throw new Error('bad status');
db.query('SELECT * FROM orders WHERE status = $1', [llmStatus]);

